import React, { useState, useEffect } from 'react';

const Opportunities = () => {
  const [opportunities, setOpportunities] = useState([]);
  const [filterWilaya, setFilterWilaya] = useState('');
  const [filterTech, setFilterTech] = useState('');

  const algeriaWilayas = ["Adrar", "Chlef", "Alger", "Constantine", "Oran", "Sétif"]; // أضف البقية هنا
  const techs = ["React", "Java", "Python", "PHP", "Flutter"];

  return (
    <div className="min-h-screen bg-gray-50 p-8 text-right" dir="rtl">
      <h1 className="text-3xl font-bold text-indigo-900 mb-8 text-center">استكشف فرص التربص</h1>

      {/* شريط الفلترة - المطلب A.3 في المستند */}
      <div className="bg-white p-6 rounded-xl shadow-sm mb-10 flex flex-wrap gap-4 items-end">
        <div className="flex-1 min-w-[200px]">
          <label className="block text-sm font-bold text-gray-700 mb-2">البحث حسب الولاية:</label>
          <select 
            className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
            onChange={(e) => setFilterWilaya(e.target.value)}
          >
            <option value="">كل الولايات</option>
            {algeriaWilayas.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>

        <div className="flex-1 min-w-[200px]">
          <label className="block text-sm font-bold text-gray-700 mb-2">حسب التقنية:</label>
          <select 
            className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
            onChange={(e) => setFilterTech(e.target.value)}
          >
            <option value="">كل التقنيات</option>
            {techs.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>

        <button className="bg-indigo-700 text-white px-8 py-2 rounded-lg font-bold hover:bg-indigo-800 transition">
          تطبيق الفلتر
        </button>
      </div>

      {/* عرض البطاقات */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* هنا تضع الـ map لبطاقاتك الحالية */}
        <div className="bg-white p-6 rounded-xl shadow-md border-t-4 border-indigo-600">
          <h3 className="text-xl font-bold mb-2">مطور واجهات (PFE)</h3>
          <p className="text-gray-500 text-sm mb-4">شركة تقنية - قسنطينة</p>
          <div className="flex gap-2 mb-4">
            <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs">React</span>
            <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs">مدفوع</span>
          </div>
          <button className="w-full py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">التقديم الآن (Apply)</button>
        </div>
      </div>
    </div>
  );
};

export default Opportunities;
